//! Named palette tables for color, shape, and linetype aesthetics.
//!
//! Named color palette tables.
//!
//! Palettes are plain lookup tables: a name maps to a static slice of
//! [`Color`]s — no hex-string parsing at use time — and a palette can
//! be wrapped straight into [`OutputRange::Colors`](crate::OutputRange::Colors).
//! Shape and linetype palettes live with their definitions in
//! [`super::shape`] and [`super::linetype`].
//!
//! Color sources: ColorBrewer, matplotlib (viridis family), D3, Tableau,
//! Kelly's colors of maximum contrast, and Fabio Crameri's scientific
//! colour maps (the 256-color tables).

// =============================================================================

use crate::color::Color;

/// const-construct an opaque sRGB color from a packed `0xRRGGBB` value,
/// so the palette tables can be `const`.
const fn hex(v: u32) -> Color {
    Color::from_rgb8((v >> 16) as u8, (v >> 8) as u8, v as u8)
}

