// =============================================================================
// Lookup
// =============================================================================

/// Look up a color palette by name.
/// Returns the palette colors as a static slice, or None if not found.
pub fn get_color_palette(name: &str) -> Option<&'static [Color]> {
    match name.to_lowercase().as_str() {
        // Categorical
        "ggsql10" | "ggsql" | "categorical" => Some(GGSQL10),
        "tableau10" | "tableau" => Some(TABLEAU10),
        "category10" | "d3" => Some(CATEGORY10),
        "set1" => Some(SET1),
        "set2" => Some(SET2),
        "set3" => Some(SET3),
        "pastel1" => Some(PASTEL1),
        "pastel2" => Some(PASTEL2),
        "dark2" => Some(DARK2),
        "paired" => Some(PAIRED),
        "accent" => Some(ACCENT),
        "kelly22" | "kelly" => Some(KELLY22),
        // Continuous sequential colormaps
        "viridis" => Some(VIRIDIS),
        "plasma" => Some(PLASMA),
        "magma" => Some(MAGMA),
        "inferno" => Some(INFERNO),
        "cividis" => Some(CIVIDIS),
        // ColorBrewer sequential
        "blues" => Some(BLUES),
        "greens" => Some(GREENS),
        "oranges" => Some(ORANGES),
        "reds" => Some(REDS),
        "purples" => Some(PURPLES),
        "greys" | "grays" => Some(GREYS),
        "ylorrd" => Some(YLORRD),
        "ylorbr" => Some(YLORBR),
        "ylgnbu" => Some(YLGNBU),
        "ylgn" => Some(YLGN),
        "purd" => Some(PURD),
        "pubugn" => Some(PUBUGN),
        "pubu" => Some(PUBU),
        "orrd" => Some(ORRD),
        "gnbu" => Some(GNBU),
        "bupu" => Some(BUPU),
        "bugn" => Some(BUGN),
        "rdpu" => Some(RDPU),
        // ColorBrewer diverging
        "rdbu" => Some(RDBU),
        "rdylbu" => Some(RDYLBU),
        "rdylgn" => Some(RDYLGN),
        "spectral" => Some(SPECTRAL),
        "brbg" => Some(BRBG),
        "prgn" => Some(PRGN),
        "piyg" => Some(PIYG),
        "rdgy" => Some(RDGY),
        "puor" => Some(PUOR),
        // Crameri scientific colour maps sequential
        "acton" => Some(ACTON),
        "bamako" => Some(BAMAKO),
        "batlow" => Some(BATLOW),
        "batlowk" => Some(BATLOWK),
        "batloww" => Some(BATLOWW),
        "bilbao" => Some(BILBAO),
        "buda" => Some(BUDA),
        "davos" => Some(DAVOS),
        "devon" => Some(DEVON),
        "glasgow" => Some(GLASGOW),
        "grayc" => Some(GRAYC),
        "hawaii" => Some(HAWAII),
        "imola" => Some(IMOLA),
        "lajolla" => Some(LAJOLLA),
        "lapaz" => Some(LAPAZ),
        "lipari" => Some(LIPARI),
        "navia" => Some(NAVIA),
        "sequential" => Some(SEQUENTIAL),
        "nuuk" => Some(NUUK),
        "oslo" => Some(OSLO),
        "tokyo" => Some(TOKYO),
        "turku" => Some(TURKU),
        // Crameri scientific colour maps multi-sequential
        "bukavu" => Some(BUKAVU),
        "fes" => Some(FES),
        "oleron" => Some(OLERON),
        // Crameri scientific colour maps diverging
        "bam" => Some(BAM),
        "berlin" => Some(BERLIN),
        "broc" => Some(BROC),
        "cork" => Some(CORK),
        "lisbon" => Some(LISBON),
        "managua" => Some(MANAGUA),
        "roma" => Some(ROMA),
        "tofino" => Some(TOFINO),
        "vanimo" => Some(VANIMO),
        "vik" | "diverging" => Some(VIK),
        // Crameri scientific colour maps cyclical
        "bamo" => Some(BAMO),
        "broco" => Some(BROCO),
        "corko" => Some(CORKO),
        "romao" | "cyclic" => Some(ROMAO),
        "viko" => Some(VIKO),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_color_palette_holds_parsed_colors() {
        // No hex-string interchange: tables are `Color` values directly.
        let viridis = get_color_palette("viridis").unwrap();
        assert_eq!(viridis[0], Color::from_rgb8(0x44, 0x01, 0x54));
        assert_eq!(viridis[255], Color::from_rgb8(0xfd, 0xe7, 0x24));
    }

    #[test]
    fn test_get_color_palette() {
        assert!(get_color_palette("viridis").is_some());
        assert!(get_color_palette("VIRIDIS").is_some()); // case insensitive
        assert!(get_color_palette("tableau10").is_some());
        assert!(get_color_palette("ggsql10").is_some());
        assert!(get_color_palette("ggsql").is_some()); // alias
        assert!(get_color_palette("kelly22").is_some());
        assert!(get_color_palette("kelly").is_some()); // alias
        assert!(get_color_palette("greys").is_some());
        assert!(get_color_palette("grays").is_some()); // alias
        assert!(get_color_palette("ylgnbu").is_some());
        assert!(get_color_palette("batlow").is_some());
        assert!(get_color_palette("roma").is_some());
        assert!(get_color_palette("unknown").is_none());
    }

    #[test]
    fn test_crameri_palette_size() {
        assert_eq!(get_color_palette("batlow").unwrap().len(), 256);
        assert_eq!(get_color_palette("hawaii").unwrap().len(), 256);
        assert_eq!(get_color_palette("roma").unwrap().len(), 256);
        assert_eq!(get_color_palette("vik").unwrap().len(), 256);
    }

    #[test]
    fn test_sequential_palette() {
        // Sequential is navia with the 20% lightest colors removed
        assert_eq!(get_color_palette("sequential").unwrap().len(), 204);
        assert_eq!(get_color_palette("navia").unwrap().len(), 256);
        assert_eq!(
            get_color_palette("sequential").unwrap()[0],
            get_color_palette("navia").unwrap()[0]
        );
    }
}
